		const inject = ["slots", "modules"];
		function apply(ctx) {
			pluginCtx = ctx;
			ensureStyles();
			fetchDepMap();
			// uSES feed over the settings.section WINNERS (entriesOfSlot): one row
			// per cell id, sorted by order. Native ids stay in the feed — HubPanel
